changeSet.sql:
ALTER TABLE source_configuration
ADD COLUMN service_type ENUM('VOICE','SMS','USAGE','DATA') NOT NULL DEFAULT 'VOICE'
COMMENT 'Service type for this source: VOICE uses duration-based cost, SMS uses message-count-based cost';

ALTER TABLE rated_cdr
ADD COLUMN message_count INT NULL
COMMENT 'Number of SMS messages — populated for SMS CDRs, null for VOICE/USAGE';
